export function ingredientType(name){
 const n=name.toLowerCase();
 if(n.includes('queso'))return 'cheese';if(n.includes('champi'))return 'mushroom';if(n.includes('tomate'))return 'tomato';if(n.includes('pollo'))return 'chicken';if(n.includes('carne'))return 'beef';if(n.includes('tocineta'))return 'bacon';if(n.includes('jamón'))return 'ham';if(n.includes('chorizo')||n.includes('peperoni')||n.includes('salchicha'))return 'pepperoni';if(n.includes('maic')||n.includes('maíz'))return 'corn';if(n.includes('piña')||n.includes('maduro'))return 'pineapple';if(n.includes('cebolla'))return 'onion';if(n.includes('camar'))return 'shrimp';if(n.includes('papas'))return 'fries';return 'leaf';
}
export function ingredientSvg(name){return `<svg viewBox="0 0 50 50" aria-hidden="true">${symbol[ingredientType(name)]}</svg>`}
export { layer as ingredientLayer };
function random(seed){let s=seed;return ()=>{s=(s*16807)%2147483647;return(s-1)/2147483646}}
function crust(id){const budget=drawingBudget();const r=random(46);let speckles='';for(let i=0;i<budget.speckles;i++){const a=r()*Math.PI*2;const rad=198+r()*18;const x=250+Math.cos(a)*rad,y=250+Math.sin(a)*rad;speckles+=`<ellipse cx="${x}" cy="${y}" rx="${1+r()*5}" ry="${1+r()*3}" transform="rotate(${r()*360} ${x} ${y})" fill="${i%3?'#87542e':'#453325'}" opacity="${.15+r()*.55}"/>`;}let cheese='';for(let i=0;i<budget.cheeseSpots;i++){const a=r()*Math.PI*2,rad=Math.sqrt(r())*173,x=250+Math.cos(a)*rad,y=250+Math.sin(a)*rad;cheese+=`<ellipse cx="${x}" cy="${y}" rx="${7+r()*19}" ry="${5+r()*16}" fill="${['#f5daa0','#e8ba67','#f8e4b0','#c7853f','#fff0c4'][i%5]}" opacity="${.25+r()*.45}"/>`;}
 return `<defs><radialGradient id="crust-${id}"><stop offset=".75" stop-color="#b57636"/><stop offset=".85" stop-color="#dba759"/><stop offset=".92" stop-color="#e8bc78"/><stop offset=".97" stop-color="#c48948"/><stop offset="1" stop-color="#9c622f"/></radialGradient><radialGradient id="cheese-${id}"><stop stop-color="#f5dba1"/><stop offset=".85" stop-color="#eac57b"/><stop offset="1" stop-color="#d6964e"/></radialGradient><clipPath id="clip-${id}"><circle cx="250" cy="250" r="218"/></clipPath></defs><g clip-path="url(#clip-${id})"><circle cx="250" cy="250" r="218" fill="url(#crust-${id})"/><circle cx="250" cy="250" r="190" fill="#b74025"/><path d="M250 63C335 62 434 139 436 249S354 440 251 435S63 350 66 249S139 62 250 63Z" fill="url(#cheese-${id})"/>${cheese}${speckles}</g>`;
}
function flavorTypes(item){const text=(item.name+' '+item.description).toLowerCase();const list=[];for(const [word,type]of [['pollo','chicken'],['champiñ','mushroom'],['piña','pineapple'],['jamón','ham'],['peperoni','pepperoni'],['tocineta','bacon'],['tomate','tomato'],['albahaca','leaf'],['maíz','corn'],['pimentón','pepper'],['cebolla','onion'],['carne','beef'],['chorizo','pepperoni'],['maduro','pineapple'],['aceituna','olive']]){if(text.includes(word)&&!list.includes(type))list.push(type)}return list.length?list:['cheese'];}
function layer(type,index,animated){animated=animated&&canAnimate();const budget=drawingBudget();const r=random(71+index*179);let content='';const count=type==='cheese'?budget.cheeseToppings:budget.toppings;for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2+index*.7+r()*.4;const radius=i<2?40+r()*30:95+r()*65;const x=250+Math.cos(a)*radius,y=250+Math.sin(a)*radius;const size=type==='cheese'?42:36+r()*12;content+=`<g transform="translate(${x-size/2} ${y-size/2}) rotate(${r()*360} ${size/2} ${size/2})"><g class="${animated?'pizza-piece':''}" style="--delay:${i*28}ms"><svg width="${size}" height="${size}" viewBox="0 0 50 50" style="overflow:visible">${symbol[type]}</svg></g></g>`;}return content;}
export function mountPizza(container,item,extras=[],scale=.87){const id=++serial;container.innerHTML=`<div class="pizza-scale" style="--pizza-scale:${scale}"><svg class="pizza-svg" viewBox="0 0 500 500" role="img" aria-label="Illustration de la pizza ${item.name}">${crust(id)}<g class="base-toppings">${flavorTypes(item).map((type,i)=>layer(type,i,false)).join('')}</g><g class="extra-toppings"></g></svg></div>`;updatePizza(container,extras,scale,false);}
export function updatePizza(container,extras,scale,animate=true){container.querySelector('.pizza-scale').style.setProperty('--pizza-scale',scale);const group=container.querySelector('.extra-toppings');const keep=new Set(extras.map(x=>x.id));for(const node of [...group.children])if(!keep.has(node.dataset.id))node.remove();for(const [index,item]of extras.entries()){if([...group.children].some(n=>n.dataset.id===item.id))continue;const node=document.createElementNS('http://www.w3.org/2000/svg','g');node.dataset.id=item.id;node.innerHTML=layer(ingredientType(item.name),index+12,animate);group.append(node);}}
